// ============================================================
// EDIT HERE IF YOUR SHIFT CHANGES
// Anchor: Sunday 12 July 2026 = Work day (index 0)
// ============================================================
const ANCHOR = new Date('2026-07-12T00:00:00.000Z');
const PATTERN = ['W','W','F','F','W','W','F','F','F','W','W','W','F','F'];
// ============================================================

function getDayType(date){
  const d = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  const a = new Date(ANCHOR.getFullYear(), ANCHOR.getMonth(), ANCHOR.getDate());
  const diffDays = Math.floor((d - a) / 86400000);
  const idx = ((diffDays % 14) + 14) % 14;
  return PATTERN[idx];
}
function isFree(date){ return getDayType(date) === 'F'; }
function addDays(d,n){ const r = new Date(d); r.setDate(r.getDate()+n); return r; }
function isGymDay(date){ return isFree(date) || isFree(addDays(date,1)); }
function dayOfYear(date){
  const start = new Date(date.getFullYear(),0,0);
  return Math.floor((date - start) / 86400000);
}

const today = new Date();
const todayType = getDayType(today);
const isFreeToday = todayType === 'F';
const isSaturday = today.getDay() === 6;
const gymToday = isGymDay(today);

// ============================================================
// MONTH 1 (July 2026) CONTENT LIBRARY — rotates so every
// free/work day gets different real content. Update this
// block when Month 2 starts.
// ============================================================
const FREE_DAY_SETS = [
  { title: 'NumPy block 1', items: ['Code NumPy exercises 1-5 (arrays, indexing, slicing)', 'Watch StatQuest: intro stats refresher (15 min)'] },
  { title: 'NumPy block 2', items: ['Code NumPy exercises 6-10 (broadcasting, aggregation)', 'Push all NumPy exercises to GitHub'] },
  { title: 'pandas - Keith Galli day 1', items: ['Watch + code along: DataFrames, CSV loading, .loc/.iloc (2.5h)', 'Use VS Code locally, not just Colab'] },
  { title: 'pandas - Keith Galli day 2', items: ['Watch + code along: groupby, merge, concat, fillna/dropna (2.5h)', 'Save your practice notebook to GitHub'] },
  { title: 'Data viz project - build', items: ['Pick a real CSV (Kaggle)', 'Clean it with pandas', 'Plot 2 of the 3 required charts (Matplotlib)'] },
  { title: 'Data viz project - finish', items: ['Plot the 3rd chart + polish all 3', 'Write the README', 'git add, commit, push to GitHub'] }
];
const WORK_DAY_SETS = [
  { title: 'Light review - NumPy', items: ['Re-read your NumPy notes, 15-20 min only', 'No new topics tonight'] },
  { title: 'Light review - pandas', items: ['Skim your pandas notebook from the last free day', '1 short StatQuest video max'] },
  { title: 'Light review - last Saturday', items: ['Reread this week\'s diploma notes', 'Note 1 question to ask next session'] }
];

const doy = dayOfYear(today);
const freeSet = FREE_DAY_SETS[doy % FREE_DAY_SETS.length];
const workSet = WORK_DAY_SETS[doy % WORK_DAY_SETS.length];

const trackTasks = [];
if (isFreeToday && !isSaturday) {
  trackTasks.push({ task: freeSet.title, time: '9:00 AM to 2:00 PM', notes: freeSet.items.join(' | '), category: 'Deep study' });
} else if (!isFreeToday) {
  trackTasks.push({ task: workSet.title, time: 'Evening, 20 min', notes: workSet.items.join(' | '), category: 'Light review' });
}
trackTasks.push({ task: 'Git commit', time: 'Before bed', notes: 'Push any code you touched today, even 1 line', category: 'Daily' });
if (isSaturday) {
  trackTasks.push({ task: 'Diploma 1 session', time: 'Full day, 6 hours', notes: 'Full focus, no distractions, take notes', category: 'Diploma' });
}

const prayers = [
  { name: 'Fajr', time: '03:45 AM' },
  { name: 'Dhuhr', time: '12:00 PM' },
  { name: 'Asr', time: '03:30 PM' },
  { name: 'Maghrib', time: '06:45 PM' },
  { name: 'Isha', time: '08:15 PM' }
];
const personalTasks = prayers.map(p => ({ task: p.name + ' prayer', time: p.time, category: 'Prayer' }));
personalTasks.push({ task: 'Read 5 pages', time: 'Any time', category: 'Reading' });
if (gymToday) {
  personalTasks.push({ task: 'Gym session', time: 'Afternoon', category: 'Gym', notes: isFreeToday ? 'Free day' : 'Day before a free day' });
}

const dayNames = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const weekPreview = [];
for (let i=0;i<7;i++){
  const d = addDays(today,i);
  weekPreview.push({ day: dayNames[d.getDay()], date: d.getDate()+'/'+(d.getMonth()+1), type: getDayType(d), isSat: d.getDay()===6, isGym: isGymDay(d) });
}

let dayMessage = isSaturday ? 'DIPLOMA DAY - 6 hours, full focus.' :
  isFreeToday ? 'FREE DAY - this is your deep study day.' :
  'WORK DAY (12H shift) - light review only tonight, rest matters too.';

return [{ json: {
  today: today.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'}),
  todayISO: today.toISOString().split('T')[0],
  todayType, isFreeToday, isSaturday, gymToday, dayMessage,
  trackTasks, personalTasks, weekPreview
}}];

const t = $('Calculate Today\'s Tasks').first().json;
let doneCount = 0, totalCount = 0;
try {
  const results = $input.first().json.results || [];
  totalCount = results.length;
  doneCount = results.filter(r => r.properties && r.properties['Done'] && r.properties['Done'].checkbox).length;
} catch(e) {}
const pct = totalCount ? Math.round((doneCount/totalCount)*100) : 0;

const trackRows = t.trackTasks.map(x => '<tr><td style="padding:10px 14px;border-bottom:1px solid #f0f0f0;font-size:14px;">' + x.task + '</td><td style="padding:10px 14px;border-bottom:1px solid #f0f0f0;font-size:12px;color:#666;">' + x.time + '</td><td style="padding:10px 14px;border-bottom:1px solid #f0f0f0;font-size:11px;color:#999;">' + (x.notes||'') + '</td></tr>').join('');
const personalRows = t.personalTasks.map(x => '<tr><td style="padding:10px 14px;border-bottom:1px solid #f0f0f0;font-size:14px;">' + x.task + '</td><td style="padding:10px 14px;border-bottom:1px solid #f0f0f0;font-size:12px;color:#666;">' + x.time + '</td><td style="padding:10px 14px;border-bottom:1px solid #f0f0f0;font-size:11px;color:#999;">' + (x.notes||x.category||'') + '</td></tr>').join('');
const weekRows = t.weekPreview.map((d,i)=>'<div style="display:inline-block;text-align:center;width:13%;margin:0 0.5%;padding:8px 4px;background:'+(i===0?'#EBF5FF':d.type==='F'?'#F0FDF4':'#FFF5F5')+';border-radius:8px;"><div style="font-size:10px;color:#888;">'+d.day+'</div><div style="font-size:12px;font-weight:600;">'+d.date+'</div><div style="font-size:9px;color:'+(d.type==='F'?'#16a34a':'#dc2626')+';">'+(d.type==='F'?'Free':'Work')+(d.isSat?' - Diploma':'')+(d.isGym?' - Gym':'')+'</div></div>').join('');

const dayColor = t.isSaturday ? '#7C3AED' : t.isFreeToday ? '#16a34a' : '#dc2626';
const DASHBOARD_URL = 'https://n8n.elnourcompany.org/webhook/loay-dashboard';
const NOTION_URL = 'https://app.notion.com/p/8f4db78d35064e61bb2741acab088145';

const html = '<!DOCTYPE html><html><body style="margin:0;padding:0;background:#f5f5f5;font-family:-apple-system,sans-serif;">' +
'<div style="max-width:600px;margin:24px auto;background:#fff;border-radius:14px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.08);">' +
'<div style="background:'+dayColor+';padding:24px 28px;">' +
'<div style="font-size:11px;color:rgba(255,255,255,0.75);text-transform:uppercase;">Good morning, Loay</div>' +
'<div style="font-size:22px;font-weight:600;color:#fff;">'+t.today+'</div></div>' +
'<div style="padding:16px 28px;background:#fafafa;border-bottom:1px solid #f0f0f0;"><p style="margin:0;font-size:13px;color:#555;">'+t.dayMessage+'</p></div>' +
'<div style="padding:16px 28px;"><div style="font-size:11px;font-weight:600;color:#999;text-transform:uppercase;margin-bottom:8px;">Progress: '+pct+'% of tracked tasks done</div>' +
'<div style="background:#eee;border-radius:20px;height:8px;overflow:hidden;"><div style="background:'+dayColor+';height:8px;width:'+pct+'%;"></div></div></div>' +
'<div style="padding:0 28px 16px;"><div style="font-size:11px;font-weight:600;color:#999;text-transform:uppercase;margin-bottom:10px;">Next 7 days</div><div>'+weekRows+'</div></div>' +
'<div style="padding:20px 28px 0;"><div style="font-size:13px;font-weight:600;color:#378ADD;text-transform:uppercase;">Track</div><table style="width:100%;border-collapse:collapse;margin-top:8px;">'+trackRows+'</table></div>' +
'<div style="padding:20px 28px 0;"><div style="font-size:13px;font-weight:600;color:#D4537E;text-transform:uppercase;">Personal</div><table style="width:100%;border-collapse:collapse;margin-top:8px;">'+personalRows+'</table></div>' +
'<div style="padding:24px 28px;text-align:center;"><a href="'+DASHBOARD_URL+'" style="display:inline-block;background:'+dayColor+';color:#fff;padding:10px 22px;border-radius:8px;text-decoration:none;font-size:13px;font-weight:600;margin-right:8px;">Open Live Dashboard</a><a href="'+NOTION_URL+'" style="display:inline-block;background:#eee;color:#333;padding:10px 22px;border-radius:8px;text-decoration:none;font-size:13px;font-weight:600;">Open Notion</a></div>' +
'</div></body></html>';

return [{ json: { html: html, subject: t.today + ' - ' + pct + '% done, ' + (t.isSaturday?'Diploma Day':t.isFreeToday?'Free Day':'Work Day') } }];

const results = $input.first().json.results || [];
const total = results.length;
const done = results.filter(r => r.properties && r.properties['Done'] && r.properties['Done'].checkbox).length;
const pct = total ? Math.round((done/total)*100) : 0;
let verdict = pct >= 80 ? 'On track - strong week.' : pct >= 50 ? 'Mixed week - pick it back up.' : 'Behind - Saturday is a reset, not a write-off.';
const html = '<div style="font-family:sans-serif;padding:24px;max-width:500px;margin:auto;background:#fff;border-radius:12px;border:1px solid #eee;"><h2 style="color:#333;">Weekly progress report</h2><p style="font-size:32px;font-weight:700;color:#378ADD;margin:8px 0;">'+pct+'%</p><p style="color:#555;">'+done+' of '+total+' recurring tasks marked done this week.</p><p style="color:#333;font-weight:600;">'+verdict+'</p></div>';
return [{ json: { html: html, subject: 'Weekly report - ' + pct + '% complete' } }];

const ANCHOR = new Date('2026-07-12T00:00:00.000Z');
const PATTERN = ['W','W','F','F','W','W','F','F','F','W','W','W','F','F'];
function getDayType(date){
  const d = new Date(date.getFullYear(), date.getMonth(), date.getDate());
  const a = new Date(ANCHOR.getFullYear(), ANCHOR.getMonth(), ANCHOR.getDate());
  const diffDays = Math.floor((d - a) / 86400000);
  return PATTERN[((diffDays % 14) + 14) % 14];
}
function isFree(d){ return getDayType(d) === 'F'; }
function addDays(d,n){ const r = new Date(d); r.setDate(r.getDate()+n); return r; }
function isGymDay(d){ return isFree(d) || isFree(addDays(d,1)); }
function pad(n){ return n<10?'0'+n:''+n; }
function iso(d,h,m){ return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+'T'+pad(h)+':'+pad(m)+':00'; }

const events = [];
const today = new Date();
for (let i=0;i<30;i++){
  const d = addDays(today,i);
  if (d.getDay()===6){
    events.push({ subject: 'Diploma 1 session', start: iso(d,9,0), end: iso(d,15,0) });
  }
  if (isGymDay(d)){
    events.push({ subject: 'Gym', start: iso(d,16,0), end: iso(d,17,30) });
  }
  if (!isFree(d) && d.getDay()!==6){
    events.push({ subject: 'Light study review', start: iso(d,21,0), end: iso(d,21,30) });
  } else if (isFree(d) && d.getDay()!==6){
    events.push({ subject: 'Deep study block', start: iso(d,9,0), end: iso(d,14,0) });
  }
}
return events.map(e => ({ json: e }));

const ANCHOR = new Date('2026-07-12T00:00:00.000Z');
const PATTERN = ['W','W','F','F','W','W','F','F','F','W','W','W','F','F'];
function getDayType(date){ const d=new Date(date.getFullYear(),date.getMonth(),date.getDate()); const a=new Date(ANCHOR.getFullYear(),ANCHOR.getMonth(),ANCHOR.getDate()); const diff=Math.floor((d-a)/86400000); return PATTERN[((diff%14)+14)%14]; }
function isFree(d){ return getDayType(d)==='F'; }
function addDays(d,n){ const r=new Date(d); r.setDate(r.getDate()+n); return r; }
function isGymDay(d){ return isFree(d) || isFree(addDays(d,1)); }
const today = new Date();
const todayType = getDayType(today);
const isSaturday = today.getDay()===6;
const isFreeToday = todayType==='F';
const gymToday = isGymDay(today);
return [{ json: { today: today.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'}), todayType, isSaturday, isFreeToday, gymToday } }];

const d = $('Dashboard - Calc Day').first().json;
const results = $input.first().json.results || [];
const TOGGLE_URL = 'https://n8n.elnourcompany.org/webhook/loay-toggle-task';

const rows = results.map(r => {
  const props = r.properties;
  const name = props['Task'] && props['Task'].title && props['Task'].title[0] ? props['Task'].title[0].plain_text : 'Untitled';
  const done = props['Done'] && props['Done'].checkbox;
  const dashboard = props['Dashboard'] && props['Dashboard'].select ? props['Dashboard'].select.name : '';
  const time = props['Time'] && props['Time'].rich_text && props['Time'].rich_text[0] ? props['Time'].rich_text[0].plain_text : '';
  const pageId = r.id;
  const link = TOGGLE_URL + '?id=' + pageId + '&status=' + (!done);
  return '<tr><td style="padding:10px 14px;border-bottom:1px solid #eee;"><a href="'+link+'" style="text-decoration:none;color:'+(done?'#999':'#1a1a1a')+';font-size:14px;'+(done?'text-decoration:line-through;':'')+'">'+name+'</a></td><td style="padding:10px 14px;border-bottom:1px solid #eee;font-size:12px;color:#888;">'+time+'</td><td style="padding:10px 14px;border-bottom:1px solid #eee;font-size:11px;color:#aaa;">'+dashboard+'</td></tr>';
}).join('');

const pct = results.length ? Math.round((results.filter(r=>r.properties['Done'].checkbox).length/results.length)*100) : 0;
const dayColor = d.isSaturday ? '#7C3AED' : d.isFreeToday ? '#16a34a' : '#dc2626';

const html = '<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:20px;background:#f5f5f5;font-family:-apple-system,sans-serif;">' +
'<div style="max-width:600px;margin:auto;background:#fff;border-radius:14px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,0.08);">' +
'<div style="background:'+dayColor+';padding:24px;"><div style="color:rgba(255,255,255,0.8);font-size:12px;text-transform:uppercase;">Live Dashboard</div><div style="color:#fff;font-size:20px;font-weight:600;">'+d.today+'</div></div>' +
'<div style="padding:16px 24px;"><div style="font-size:11px;color:#999;text-transform:uppercase;margin-bottom:6px;">Today: '+pct+'% complete</div><div style="background:#eee;border-radius:20px;height:8px;"><div style="background:'+dayColor+';height:8px;width:'+pct+'%;border-radius:20px;"></div></div></div>' +
'<div style="padding:0 24px 24px;"><table style="width:100%;border-collapse:collapse;">'+rows+'</table></div>' +
'<div style="padding:16px 24px;background:#fafafa;font-size:11px;color:#aaa;">Tap any task to check or uncheck it - it saves straight to Notion.</div>' +
'</div></body></html>';

return [{ json: { html: html } }];

const body = $input.first().json.body || $input.first().json;
const repo = body.repository ? body.repository.name : 'unknown-repo';
const pusher = body.pusher ? body.pusher.name : 'unknown';
const commits = body.commits || [];
const commitCount = commits.length;
const commitMessages = commits.map(c => c.message).join(' | ');
const today = new Date();
return [{ json: {
  repo, pusher, commitCount, commitMessages,
  todayISO: today.toISOString().split('T')[0],
  todayLabel: today.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'})
}}];

const results = $input.first().json.results || [];
const gitTask = results.find(r => {
  const t = r.properties['Task'] && r.properties['Task'].title && r.properties['Task'].title[0];
  return t && t.plain_text.trim().toLowerCase() === 'git commit';
});
if (!gitTask) {
  throw new Error('Could not find the "Git commit" row in your Notion Daily Checklist database');
}
return [{ json: { pageId: gitTask.id } }];

const push = $('Extract Push Info').first().json;
const staticData = $getWorkflowStaticData('global');
const today = push.todayISO;

if (staticData.lastPushDate === today) {
  // already counted today, don't double count
} else if (staticData.lastPushDate) {
  const last = new Date(staticData.lastPushDate);
  const cur = new Date(today);
  const diffDays = Math.round((cur - last) / 86400000);
  staticData.streak = diffDays === 1 ? (staticData.streak || 0) + 1 : 1;
} else {
  staticData.streak = 1;
}
staticData.lastPushDate = today;

return [{ json: {
  repo: push.repo, commitCount: push.commitCount, commitMessages: push.commitMessages,
  todayLabel: push.todayLabel, streak: staticData.streak
}}];

const d = $input.first().json;
const html = '<div style="font-family:sans-serif;padding:20px;max-width:500px;margin:auto;background:#F0FDF4;border-radius:12px;">' +
  '<h2 style="color:#16a34a;margin:0 0 8px;">Push detected</h2>' +
  '<p style="color:#333;line-height:1.6;">' + d.commitCount + ' commit(s) pushed to <strong>' + d.repo + '</strong> today.</p>' +
  '<p style="color:#333;">Current streak: <strong>' + d.streak + ' day(s)</strong></p>' +
  '<p style="color:#888;font-size:12px;margin-top:12px;">Notion Git commit task marked done automatically.</p>' +
  '</div>';
return [{ json: { html: html, subject: 'Pushed to ' + d.repo + ' - streak ' + d.streak } }];
